53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const COMPONENT_TYPES = ["rune", "moonstone"];
65	const COMPONENT_BLOCK_SIZE = 3;
66	const COMPONENT_BLOCK_PREMIUM = 60;
67	
68	const CURSE_SURCHARGE_PERCENT = 50;
69	const HIGH_ENCHANTMENT_THRESHOLD = 5;
70	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
71	
72	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
73	const LOYALTY_DISCOUNT_PERCENT = 20;
74	const LOYALTY_MINIMUM_YEARS = 2;
75	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
76	
77	// Integer multiply before divide keeps fractional percentages exact
78	// (e.g. 10% of 25 is exactly 2.5 — no float noise from multiplying by 1.1).
79	const percentOf = (amount: number, percent: number): number =>
80	  (amount * percent) / 100;
81	
82	const isComponent = (item: QuoteItem): boolean =>
83	  COMPONENT_TYPES.includes(item.type);
84	
85	const basePremiumOf = (item: QuoteItem): number => BASE_PREMIUMS[item.type];
86	
87	const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
88	  values.reduce((sum, value) => sum + amount(value), 0);
89	
90	const isCursed = (item: QuoteItem): boolean => item.cursed === true;
91	
92	const isHighlyEnchanted = (item: QuoteItem): boolean =>
93	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
94	
95	// Item surcharge: a fixed percent of each qualifying item's base premium.
96	const itemSurcharge = (
97	  items: QuoteItem[],
98	  applies: (item: QuoteItem) => boolean,
99	  percent: number
100	): number =>
101	  sumBy(items.filter(applies), (item) => percentOf(basePremiumOf(item), percent));
102	
103	// Pricing rule: a block of exactly 3 alike components costs a flat block premium.
104	const componentTypePremium = (items: QuoteItem[], type: string): number => {
105	  const count = items.filter((item) => item.type === type).length;
106	  return count === COMPONENT_BLOCK_SIZE
107	    ? COMPONENT_BLOCK_PREMIUM
108	    : count * BASE_PREMIUMS[type];
109	};
110	
111	const quotePremium = (
112	  items: QuoteItem[],
113	  customer: Customer,
114	  isFollowUpContract: boolean
115	): number => {
116	  const componentsPremium = sumBy(COMPONENT_TYPES, (type) =>
117	    componentTypePremium(items, type)
118	  );
119	  const mainItemsPremium = sumBy(
120	    items.filter((item) => !isComponent(item)),
121	    basePremiumOf
122	  );
123	  const policyBasePremium = componentsPremium + mainItemsPremium;
124	  const curseSurcharge = itemSurcharge(items, isCursed, CURSE_SURCHARGE_PERCENT);
125	  const enchantmentSurcharge = itemSurcharge(
126	    items,
127	    isHighlyEnchanted,
128	    HIGH_ENCHANTMENT_SURCHARGE_PERCENT
129	  );
130	  // Policy-wide modifiers are all computed on the unmodified policy base.
131	  const firstInsuranceSurcharge = percentOf(
132	    policyBasePremium,
133	    FIRST_INSURANCE_SURCHARGE_PERCENT
134	  );
135	  const loyaltyDiscount =
136	    customer.yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS
137	      ? percentOf(policyBasePremium, LOYALTY_DISCOUNT_PERCENT)
138	      : 0;
139	  const followUpContractDiscount = isFollowUpContract
140	    ? percentOf(policyBasePremium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
141	    : 0;
142	  return Math.ceil(
143	    policyBasePremium +
144	      curseSurcharge +
145	      enchantmentSurcharge +
146	      firstInsuranceSurcharge -
147	      loyaltyDiscount -
148	      followUpContractDiscount +
149	      PROCESSING_FEE
150	  );
151	};
152	
153	const INSURANCE_VALUES: Record<string, number> = {
154	  sword: 1000,
155	  amulet: 600,
156	  rune: 250,
157	};
158	
159	const DEDUCTIBLE = 100;
160	const CAP_MULTIPLIER = 2; // payout cap is twice the policy's insurance sum
161	
162	const insuranceSumOf = (items: QuoteItem[]): number =>
163	  sumBy(items, (item) => INSURANCE_VALUES[item.type]);
164	
165	// Claim clause: items enchanted at or above this level are only reimbursed
166	// at 50%. Distinct rule from the premium's HIGH_ENCHANTMENT_THRESHOLD (5).
167	const CLAIM_HALVING_ENCHANTMENT_THRESHOLD = 8;
168	const HALVED_REIMBURSEMENT_PERCENT = 50;
169	
170	const reimbursementFor = (
171	  policyItems: QuoteItem[],
172	  damage: Damage
173	): number => {
174	  const insuredItem = policyItems.find(
175	    (item) => item.type === damage.itemType
176	  );
177	  return (insuredItem?.enchantment ?? 0) >= CLAIM_HALVING_ENCHANTMENT_THRESHOLD
178	    ? percentOf(damage.amount, HALVED_REIMBURSEMENT_PERCENT)
179	    : damage.amount;
180	};
181	
182	const settleClaim = (
183	  policyItems: QuoteItem[],
184	  damages: Damage[]
185	): ClaimResult => {
186	  const cap = CAP_MULTIPLIER * insuranceSumOf(policyItems);
187	  // Payouts round down in MHPCO's favor — mirrors the Math.ceil on premiums.
188	  const desiredPayout = Math.floor(
189	    sumBy(damages, (damage) => reimbursementFor(policyItems, damage) - DEDUCTIBLE)
190	  );
191	  const payout = Math.min(desiredPayout, cap);
192	  return { payout, remainingCap: cap - payout };
193	};
194	
195	export const runScenario = (scenario: Scenario): ScenarioResult => {
196	  const policies: QuoteItem[][] = [];
197	  const results = scenario.steps.map((step, index): StepResult => {
198	    if (step.op === "quote") {
199	      policies[index] = step.items;
200	      return {
201	        premium: quotePremium(step.items, scenario.customer, index > 0),
202	      };
203	    }
204	    return settleClaim(policies[step.policy], step.incident.damages);
205	  });
206	  return { results };
207	};
